<script setup lang="ts">
import {computed,onMounted,onUnmounted,ref} from 'vue'
import type {createAdminAuth} from './auth'
import {downloadBackup,inspectBackupFile} from './backup-files'
import type {BackupStatus,BackupSummary,RestorePlan} from '../../src/domain/recovery'
const props=defineProps<{auth:ReturnType<typeof createAdminAuth>}>()
const status=ref<BackupStatus|null>(null),backups=ref<BackupSummary[]>([]),plan=ref<RestorePlan|null>(null),confirmation=ref(''),busy=ref(false),error=ref(''),notice=ref(''),uncertain=ref(false),fileName=ref(''),progress=ref('')
const ready=computed(()=>status.value?.enabled&&status.value.guardsReady)
const changed=computed(()=>plan.value?.summary.filter(row=>row.created+row.updated+row.removed>0)||[])
const labels:Record<string,string>={users:'用户资料与收藏',leaderTeamBindings:'领队与球队绑定',teams:'球队资料',players:'球员档案',competitions:'赛事配置',registrations:'报名记录',registrationFiles:'报名材料',matches:'赛程与赛果',resultRevisions:'赛果历史',newsArticles:'新闻公告',newsImages:'新闻图片',teamBadges:'球队队徽',platformSettings:'平台设置',matchLiveEntries:'图文直播',matchLiveImages:'直播图片',evaluationConfigs:'评分窗口',playerRatings:'球员评分',playerComments:'球员评论',playerAwards:'MVP与阵容'}
let disposed=false,requestId=''
const auth=props.auth.authorized
const time=(value:string)=>new Intl.DateTimeFormat('zh-CN',{dateStyle:'medium',timeStyle:'short',timeZone:'Asia/Shanghai'}).format(new Date(value))
async function run(operation:()=>Promise<void>){if(busy.value)return;busy.value=true;error.value='';notice.value='';try{await operation()}catch(value){if(!disposed)error.value=value instanceof Error?value.message:'备份服务暂不可用。'}finally{if(!disposed){busy.value=false;progress.value=''}}}
async function refresh(){await run(async()=>{const s=await auth((api,token)=>api.backupStatus(token));if(disposed)return;status.value=s;if(s.enabled){const rows=await auth((api,token)=>api.backups(token));if(!disposed)backups.value=rows}})}
async function exportBackup(){await run(async()=>{requestId ||= Array.from(crypto.getRandomValues(new Uint8Array(16)),n=>n.toString(16).padStart(2,'0')).join('');progress.value='正在生成云端备份与最终文件归档…';const row=await auth((api,token)=>api.createBackup(token,requestId));requestId='';if(disposed)return;backups.value=[row,...backups.value.filter(b=>b.id!==row.id)];await saveFile(row);if(!disposed)notice.value='备份已生成，JSON校验通过并开始下载。'})}
async function saveFile(row:BackupSummary){await downloadBackup(row,index=>{progress.value=`正在下载备份 ${index+1}/${Math.ceil(row.bytes/32768)}…`;return auth((api,token)=>api.backupChunk(token,row.id,row.digest,index))})}
async function download(row:BackupSummary){await run(async()=>{await saveFile(row);if(!disposed)notice.value='JSON校验通过，已开始下载。'})}
async function upload(event:Event){const input=event.target as HTMLInputElement,file=input.files?.[0];input.value='';if(!file||busy.value)return;plan.value=null;confirmation.value='';fileName.value=file.name;await run(async()=>{if(!status.value)throw new Error('请先读取备份状态。');progress.value='正在校验JSON、关联数据和归档文件…';const selected=await inspectBackupFile(file,status.value.environment);const result=await auth((api,token)=>api.previewBackup(token,selected.id,selected.digest));if(!disposed){plan.value=result;uncertain.value=false;notice.value='校验通过，请核对恢复差异。预览有效期10分钟。'}})}
async function apply(){if(!plan.value||confirmation.value!==plan.value.confirmation||uncertain.value)return;const selected=plan.value;await run(async()=>{progress.value='正在创建回退备份并恢复，完成前请保持页面打开…';try{const result=await auth((api,token)=>api.applyBackup(token,selected.id,confirmation.value));if(disposed)return;notice.value=`恢复完成。回退备份：${result.rollbackId}。请重新进入业务页面读取最新数据。`;plan.value=null;confirmation.value='';backups.value=await auth((api,token)=>api.backups(token))}catch(value){if(!disposed)uncertain.value=true;throw value}})}
async function checkResult(){if(!plan.value)return;await run(async()=>{const result=await auth((api,token)=>api.backupResult(token,plan.value!.id));if(disposed)return;if(result.status==='completed'){notice.value=`恢复已完成。回退备份：${result.rollbackId}。`;plan.value=null;uncertain.value=false;backups.value=await auth((api,token)=>api.backups(token))}else{uncertain.value=false;plan.value=null;confirmation.value='';notice.value='尚未记录恢复完成，请重新选择JSON并校验当前差异后再操作。'}})}
onMounted(()=>void refresh());onUnmounted(()=>{disposed=true})
</script>
<template><section class="backup-admin"><div class="workspace-heading"><div><span class="eyebrow">数据维护</span><h1>备份与恢复</h1><p class="muted">保存业务数据及最终文件归档，恢复前核对差异并自动创建回退备份。</p></div><button class="secondary-button" :disabled="busy" @click="refresh">重新读取备份</button></div>
 <p v-if="error" class="notice" role="alert">{{error}}</p><p v-if="notice" class="notice success" role="status">{{notice}}</p><p v-if="progress" class="muted" role="status">{{progress}}</p>
 <p v-if="status&&!ready" class="environment-notice" role="status">{{!status.enabled?'备份恢复尚未启用。完成云函数部署与备份开关配置后可使用。':'业务云函数的恢复保护尚未全部就绪，请完成部署。'}}</p>
 <div class="backup-grid"><section class="account-card"><h2>导出业务备份</h2><p class="muted">涵盖赛事、球队、报名、赛果、新闻、直播、评分评选及用户资料等19类业务集合。管理员密码与登录会话独立保留。</p><p class="muted">JSON包含联系方式等业务资料，请妥善保管；图片和材料另存为当前云环境内的私有归档。</p><button class="primary-button" :disabled="busy||!ready" @click="exportBackup">{{busy?'处理中…':'生成并下载JSON备份'}}</button><p v-if="status" class="backup-limits muted">本轮支持{{status.limits.records}}条业务记录、2MiB JSON、{{status.limits.assets}}个最终文件（合计32MiB）；单次原子恢复最多{{status.limits.changes}}条差异。</p></section>
 <section class="account-card"><h2>校验与恢复</h2><p class="muted">选择当前环境导出的原始JSON。系统将核对云端原件、关联记录和文件完整性；恢复会按备份替换业务范围，包括删除备份中不存在的记录。</p><label for="backup-json" class="backup-file-label">选择JSON备份</label><input id="backup-json" type="file" accept=".json,application/json" :disabled="busy||!ready||uncertain" @change="upload"/><p v-if="fileName" class="muted backup-filename">{{fileName}}</p><p class="muted">仅支持当前环境已登记且云端归档完整的备份。跨环境导入需另行迁移。</p></section></div>
 <section v-if="plan" class="account-card backup-preview"><h2>恢复差异预览</h2><p>将变更{{plan.totalChanges}}条记录，核验{{plan.assetCount}}个最终文件。预览截止：{{time(plan.expiresAt)}}（北京时间）。</p><div class="backup-table-scroll"><table><thead><tr><th>业务范围</th><th>新增</th><th>替换</th><th>删除</th></tr></thead><tbody><tr v-for="row in changed" :key="row.collection"><td>{{labels[row.collection]||row.collection}}</td><td>{{row.created}}</td><td>{{row.updated}}</td><td>{{row.removed}}</td></tr><tr v-if="!changed.length"><td colspan="4">业务数据与备份一致，无记录差异。</td></tr></tbody></table></div><p class="notice">执行前会另存当前状态；预览后若有新数据提交，本次恢复将拒绝执行，需重新校验。恢复后的版本号递增，旧页面须重新读取。</p><label for="backup-confirmation">请输入“{{plan.confirmation}}”确认恢复</label><input id="backup-confirmation" v-model="confirmation" :disabled="busy||uncertain" autocomplete="off" :spellcheck="false"/><div class="backup-actions"><button class="danger-button" :disabled="busy||uncertain||confirmation!==plan.confirmation" @click="apply">确认执行恢复</button><button class="secondary-button" :disabled="busy" @click="checkResult">检查恢复结果</button></div><p v-if="uncertain" class="notice" role="status">本次执行结果尚未确认，请先检查恢复结果，再决定下一步。</p></section>
 <section class="account-card backup-history"><h2>最近云端备份</h2><p v-if="!backups.length" class="muted">{{status?.enabled?'暂无完整备份。':'启用后可查看云端备份。'}}</p><div v-for="row in backups" :key="row.id" class="backup-history-row"><div><strong>{{row.kind==='before_restore'?'恢复前回退备份':'手动业务备份'}}</strong><span class="muted">{{time(row.createdAt)}} · {{row.records}}条记录 · {{row.assetCount}}个文件</span><code>{{row.id}}</code></div><button class="secondary-button" :disabled="busy" @click="download(row)">下载JSON</button></div></section>
</section></template>
